"node -e '
const TmdbClient = require("./app/js/tmdb.js");
const assert = require("assert");

// Let us mock global fetch to populate the cache with 120 unique items
let fetchCounter = 0;
global.fetch = function(url) {
  fetchCounter++;
  const idMatch = url.match(/\/movie\/(\d+)/);
  const id = idMatch ? idMatch[1] : fetchCounter;
  return Promise.resolve({
    ok: true,
    json: () => Promise.resolve({ id: Number(id), title: "Movie " + id, results: [] })
  });
};

async function testCache() {
  TmdbClient.init({ cacheCapacity: 100 });
  TmdbClient.clearCache();

  // Load 120 items
  for (let i = 1; i <= 120; i++) {
    await TmdbClient.getDetails("movie", i);
  }

  const stats = TmdbClient.getCacheStats();
  console.log("Stats after 120 entries:", stats);
  assert.strictEqual(stats.size, 100, "Cache size must be strictly capped at 100");
  assert.strictEqual(stats.evictions, 20, "Must have evicted exactly 20 items");

  // Items 1-20 should have been evicted; fetching item 1 should trigger a network call (miss)
  const beforeCount = fetchCounter;
  await TmdbClient.getDetails("movie", 1);
  assert.strictEqual(fetchCounter, beforeCount + 1, "Item 1 was evicted so fetch must occur");

  // Fetching item 120 should be a hit (no network call)
  const countBeforeHit = fetchCounter;
  await TmdbClient.getDetails("movie", 120);
  assert.strictEqual(fetchCounter, countBeforeHit, "Item 120 should still be in cache");

  console.log("LRU Eviction & Capacity Capping Verified Successfully!");
}

testCache().catch(err => { console.error(err); process.exit(1); });
'"

"node -e '
const TmdbClient = require("./app/js/tmdb.js");
const assert = require("assert");

let failMode = false;
global.fetch = function(url) {
  if (failMode) {
    return Promise.reject(new Error("Simulated network outage"));
  }
  return Promise.resolve({
    ok: true,
    json: () => Promise.resolve({ id: 999, title: "Original Title", results: [] })
  });
};

async function testTtlAndStaleFallback() {
  TmdbClient.clearCache();

  // Fetch with very short TTL by overriding discover or calling mock
  // Let us test executeRequest behavior with failMode
  const item = await TmdbClient.getDetails("movie", 999);
  assert.strictEqual(item.title, "Original Title");

  // Now simulate network failure
  failMode = true;

  // Stale cache should serve the item even if network fails!
  const staleItem = await TmdbClient.getDetails("movie", 999);
  assert.strictEqual(staleItem.title, "Original Title", "Must serve stale cached item on network failure");

  // If item was never in cache, network failure should return structured error object without crashing
  const unknownItem = await TmdbClient.getDetails("movie", 88888);
  console.log("Network failure on unknown item:", unknownItem);
  assert.ok(unknownItem.error, "Should return structured error object on network failure");
  assert.strictEqual(unknownItem.code, "NETWORK_ERROR");

  console.log("TTL & Stale-While-Revalidate Fallback Verified Successfully!");
}

testTtlAndStaleFallback().catch(err => { console.error(err); process.exit(1); });
'"

"node -e '
const TmdbClient = require("./app/js/tmdb.js");
const assert = require("assert");

// Mock hanging fetch
global.fetch = function(url, opts) {
  return new Promise((resolve, reject) => {
    if (opts.signal) {
      opts.signal.addEventListener("abort", () => {
        const abortErr = new Error("This operation was aborted");
        abortErr.name = "AbortError";
        reject(abortErr);
      });
    }
    // never resolve on its own
  });
};

async function testTimeout() {
  TmdbClient.init({ requestTimeoutMs: 150 });
  TmdbClient.clearCache();

  const start = Date.now();
  const res = await TmdbClient.getDetails("movie", 555);
  const elapsed = Date.now() - start;

  console.log("Elapsed ms:", elapsed, "Response:", res);
  assert.ok(elapsed >= 140 && elapsed < 500, "Should abort around ~150ms");
  assert.ok(res.error, "Should return structured error");
  assert.strictEqual(res.code, "TIMEOUT");

  console.log("Timeout with AbortController Verified Successfully!");
}

testTimeout().catch(err => { console.error(err); process.exit(1); });
'"

